def dehydrate_point(value):
    """Dehydrator for Point data."""
    if value is None:
        return None
    # Attempt to extract coordinates from a Point-like object
    try:
        x = value.x
        y = value.y
        z = getattr(value, 'z', None)
    except AttributeError:
        # Fallback: treat value as a sequence (e.g., tuple, list)
        try:
            x, y = value[0], value[1]
            z = value[2] if len(value) > 2 else None
        except Exception as exc:
            raise TypeError("Unsupported type for point dehydration") from exc
    result = {'x': x, 'y': y}
    if z is not None:
        result['z'] = z
    return result<|return|>

