def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys are specified, return all values in order
    if not keys:
        # Prefer the dict-like values() method if available
        if hasattr(self, "values"):
            return list(self.values())
        # Fallback: iterate over the record itself
        return list(self)

    # Gather the list of keys in order
    if hasattr(self, "keys"):
        all_keys = list(self.keys())
    else:
        # If the object is not dict-like, treat it as a sequence
        all_keys = list(range(len(self)))

    result = []
    for k in keys:
        if isinstance(k, int):
            idx = k
            if idx < 0:
                idx += len(all_keys)
            if idx < 0 or idx >= len(all_keys):
                raise IndexError(f"Index {k} out of range")
            key = all_keys[idx]
            result.append(self[key])
        else:
            # Assume k is a key
            result.append(self[k])
    return result<|return|>

def data(self, *keys):
    """Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Assume the record stores field names in self._fields and
    # corresponding values in self._values.
    if not keys:
        return dict(zip(self._fields, self._values))

    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._values):
                raise IndexError(f"Index {key} out of bounds")
            field_name = self._fields[key]
            result[field_name] = self._values[key]
        else:
            # Treat as a field name
            if key in self._fields:
                idx = self._fields.index(key)
                result[key] = self._values[idx]
            else:
                result[key] = None
    return result<|return|>

def deprecated(message):
    """Decorator for deprecating functions and methods.

    Example:
        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(
                f"{func.__name__} is deprecated: {message}",
                DeprecationWarning,
                stacklevel=2
            )
            return func(*args, **kwargs)
        return wrapper
    return decorator<|return|>

