def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock:
                with lock:
                    try:
                        return cache[k]
                    except KeyError:
                        result = func(*args, **kwargs)
                        cache[k] = result
                        return result
            else:
                try:
                    return cache[k]
                except KeyError:
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator<|return|>

