    def decorator(func):
        def wrapper(*args, **kwargs):
            # Compute the cache key
            k = key(*args, **kwargs) if callable(key) else key
            if lock:
                with lock:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
            else:
