                result = func(*args, **kwargs)
                cache[k] = result
                return result
        return wrapper
    return decorator<|return|>

@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception into a readable string with a limited stack trace depth
        and truncated file paths.
        """
        def _truncate_path(path, max_parts):
            parts = path.split(os.sep)
            if len(parts) <= max_parts:
                return path
            return os.sep.join(parts[-max_parts:])

        def _format_traceback(tb, level=0):
            lines = []
            for frame in traceback.extract_tb(tb, limit=max_level):
                file_path = _truncate_path(frame.filename, max_path_level)
                lines.append(f'{"    " * level}File "{file_path}", line {frame.lineno}, in {frame.name}')
                if frame.line:
                    lines.append(f'{"    " * level}    {frame.line.strip()}')
            return "\n".join(lines)

        def _format_exception(exc, level=0):
            exc_type = type(exc).__name__
            exc_msg = str(exc)
            header = f'{"    " * level}{exc_type}: {exc_msg}'
            tb_str = _format_traceback(exc.__traceback__, level)
            result = header
            if tb_str:
                result += "\n" + tb_str
            # Handle chained exceptions
            cause = exc.__cause__ or exc.__context__
            if cause:
                result += "\n" + _format_exception(cause, level + 1)
            return result

        return _format_exception(e)<|return|>

