def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """
    Return a mapping of attribute names to their descriptions as defined by the
    interface.  If *all* is True, include every attribute that is not a
    private member or a method, even if it has no description.
    """
    descriptions = {}
    # Helper to fetch description from a class-level mapping if present
    def _get_desc(name):
        if hasattr(self.__class__, "_descriptions"):
            return self.__class__._descriptions.get(name)
        return None

    # Inspect class attributes (excluding methods and private names)
    for name, value in vars(self.__class__).items():
        if name.startswith("_") or callable(value):
            continue
        desc = _get_desc(name)
        if all or desc is not None:
            descriptions[name] = desc

    # Inspect instance attributes (excluding methods and private names)
    for name, value in vars(self).items():
        if name.startswith("_") or callable(value):
            continue
        if name in descriptions:
            continue  # already handled by class attribute
        desc = _get_desc(name)
        if all or desc is not None:
            descriptions[name] = desc

    return descriptions<|return|>

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        # Expand nested iterables (lists or tuples)
        if isinstance(item, (list, tuple)):
            _normalizeargs(item, output)
        # Handle Declarion-like objects that expose interfaces
        elif hasattr(item, "__interfaces__"):
            interfaces = getattr(item, "__interfaces__")
            if isinstance(interfaces, (list, tuple)):
                output.extend(interfaces)
            else:
                output.append(interfaces)
        elif hasattr(item, "interfaces"):
            interfaces = getattr(item, "interfaces")
            if isinstance(interfaces, (list, tuple)):
                output.extend(interfaces)
            else:
                output.append(interfaces)
        else:
            # Assume it's an individual interface or implements spec
            output.append(item)
    return output<|return|>

