def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively generate a default observer_schema dictionary from a Kubernetes manifest dictionary.
    Non-dict and non-list values are replaced with None. When first_level is True, identifying
    fields ('apiVersion', 'kind', 'metadata') are copied from the original manifest.
    """
    # Fields that should be copied verbatim when generating the top-level schema
    IDENTIFYING_FIELDS = {"apiVersion", "kind", "metadata"}

    result = {}
    for key, value in manifest_dict.items():
        # Copy identifying fields unchanged at the top level
        if first_level and key in IDENTIFYING_FIELDS:
            result[key] = value
            continue

        # Recurse into nested dictionaries
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        # Recurse into lists
        elif isinstance(value, list):
            # Assume generate_default_observer_schema_list is defined elsewhere
            result[key] = generate_default_observer_schema_list(value, first_level=False)
        # Replace all other values with None
        else:
            result[key] = None

    return result<|return|>

