        # Ensure the manifest list has a corresponding element
        if idx >= len(last_applied_manifest):
            last_applied_manifest.append({})
        manifest_item = last_applied_manifest[idx]

        # Skip non-dict items
        if not isinstance(resp_item, dict):
            continue

        # Process each field defined in the observer schema
        for field in observer_schema:
            name = field.get("name")
            if not name:
                continue

            # Initialize the field if it is missing in the manifest
            if name not in manifest_item and name in resp_item:
                manifest_item[name] = resp_item[name]

            # Handle nested structures
            field_type = field.get("type")
            if field_type == "dict":
                sub_schema = field.get("schema", [])
                sub_resp = resp_item.get(name, {})
                sub_manifest = manifest_item.get(name, {})
                if isinstance(sub_resp, dict) and isinstance(sub_manifest, dict):
                    update_last_applied_manifest_dict_from_resp(
                        sub_manifest, sub_schema, sub_resp
                    )
            elif field_type == "list":
                sub_schema = field.get("items", [])
                sub_resp = resp_item.get(name, [])
                sub_manifest = manifest_item.get(name, [])
                if isinstance(sub_resp, list) and isinstance(sub_manifest, list):
                    update_last_applied_manifest_list_from_resp(
