def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if prior is None:
        raise ValueError("prior must not be None")
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same class as self")
    # Ensure both objects have the required attributes
    for attr in ("version", "inventory"):
        if not hasattr(self, attr) or not hasattr(prior, attr):
            raise AttributeError(f"Both objects must have a '{attr}' attribute")
    # Version check: prior must be older
    if prior.version >= self.version:
        raise ValueError(f"prior.version ({prior.version}) must be less than self.version ({self.version})")
    # Timestamp check if present
    if hasattr(self, "timestamp") and hasattr(prior, "timestamp"):
        if prior.timestamp >= self.timestamp:
            raise ValueError(f"prior.timestamp ({prior.timestamp}) must be less than self.timestamp ({self.timestamp})")
    # Inventory key subset check
    if not isinstance(self.inventory, dict) or not isinstance(prior.inventory, dict):
        raise TypeError("inventory attributes must be dictionaries")
    if not set(prior.inventory.keys()).issubset(set(self.inventory.keys())):
        raise ValueError("prior.inventory keys must be a subset of self.inventory keys")
    return True<|return|>

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Base state for the requested version
    base_state = inventory.get(version, {})
    # Ensure each value is a set
    result = {lp: set(files) for lp, files in base_state.items()}

    # Determine later versions (assumes versions are comparable)
    try:
        sorted_versions = sorted(inventory.keys())
    except Exception:
        # Fallback: use the keys as provided
        sorted_versions = list(inventory.keys())

    # Find the index of the current version
    try:
        idx = sorted_versions.index(version)
    except ValueError:
        idx = -1  # If not found, treat as last

    # Merge content files from later versions for the same logical paths
    for later_version in sorted_versions[idx + 1 :]:
        later_state = inventory.get(later_version, {})
        for lp, files in later_state.items():
            if lp in result:
                result[lp].update(files)
    return result<|return|>

