def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    lines = [f"{indent_str}{self.__class__.__name__}("]
    for key, value in self.__dict__.items():
        if isinstance(value, (list, tuple)):
            lines.append(f"{indent_str}  {key}=[")
            for item in value:
                if hasattr(item, "pretty"):
                    lines.append(item.pretty(indent + 4, debug))
                else:
                    lines.append(f"{' ' * (indent + 4)}{repr(item)}")
            lines.append(f"{indent_str}  ],")
        elif hasattr(value, "pretty"):
            lines.append(f"{indent_str}  {key}=")
            lines.append(value.pretty(indent + 4, debug))
        else:
            lines.append(f"{indent_str}  {key}={repr(value)},")
    lines.append(f"{indent_str})")
    if debug:
        lines.append(f"{indent_str}# Debug: {self.__class__.__name__} at {hex(id(self))}")
    return "\n".join(lines)<|return|>

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        import subprocess
        # Get the full commit hash
        rev = subprocess.check_output(
            ["git", "rev-parse", "HEAD"],
            stderr=subprocess.DEVNULL,
        ).decode().strip()
        # Get a descriptive tag string
        describe = subprocess.check_output(
            ["git", "describe", "--tags", "--dirty", "--always"],
            stderr=subprocess.DEVNULL,
        ).decode().strip()
        # Normalize the describe string
        if describe.startswith("v"):
            describe = describe[1:]
        if "-" in describe:
            parts = describe.split("-")
            if len(parts) >= 3:
                tag, commits, sha = parts[0], parts[1], parts[2]
                version = f"{tag}.post{commits}+{sha}"
            else:
                version = describe
        else:
            version = describe
        return {"version": version, "full-revisionid": rev}
    except Exception:
        # Fallback to a default version if anything fails
        return {"version": "0+unknown", "full-revisionid": "unknown"}<|return|>

