def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Determine the iterable of objects (list, tuple, or dict values)
    objs = getattr(self, "storage_root", [])
    if isinstance(objs, dict):
        iterable = objs.values()
    else:
        iterable = objs

    for obj in iterable:
        num_objects += 1
        valid = True

        # Validate the object if requested
        if validate_objects:
            if hasattr(obj, "validate"):
                try:
                    valid = bool(obj.validate())
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"Warning: validation failed for {obj} with error: {e}")
            else:
                if show_warnings:
                    print(f"Warning: object {obj} has no validate method.")
                valid = False

        # Check the digest if requested and the object passed validation
        if check_digests and valid:
            if hasattr(obj, "check_digest"):
                try:
                    digest_ok = bool(obj.check_digest())
                except Exception as e:
                    digest_ok = False
                    if show_warnings:
                        print(f"Warning: digest check failed for {obj} with error: {e}")
                if not digest_ok:
                    valid = False
            else:
                if show_warnings:
                    print(f"Warning: object {obj} has no check_digest method.")
                valid = False

        if valid:
            good_objects += 1
        else:
            if show_warnings:
                print(f"Warning: object {obj} failed validation.")

    return num_objects, good_objects<|return|>

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure params is a dictionary
    if not isinstance(params, dict):
        params = {}
    # If bug_ids is provided, add or merge it into the params
    if bug_ids:
        # Convert bug_ids to a list of integers if possible
        try:
            bug_ids_list = [int(b) for b in bug_ids]
        except Exception:
            bug_ids_list = list(bug_ids)
        # Merge with existing 'ids' entry if present
        if 'ids' in params:
            existing = params['ids']
            if isinstance(existing, str):
                try:
                    existing_list = [int(x) for x in existing.split(',')]
                except Exception:
                    existing_list = []
            elif isinstance(existing, (list, tuple)):
                existing_list = list(existing)
            else:
                existing_list = []
            # Combine and deduplicate
            combined = sorted(set(existing_list + bug_ids_list))
            params['ids'] = ','.join(str(i) for i in combined)
        else:
