def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    # Quick checks for common loopback names
    if host in ("localhost", "127.0.0.1", "::1"):
        return True
    try:
        # Resolve the host to all possible IP addresses
        host_addrs = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    # Gather local IP addresses
    local_ips = {"127.0.0.1", "::1"}
    try:
        local_host = socket.gethostname()
        local_addrs = socket.getaddrinfo(local_host, None)
        for info in local_addrs:
            local_ips.add(info[4][0])
    except Exception:
        pass
    # Compare resolved addresses with local addresses
    for info in host_addrs:
        ip = info[4][0]
        if ip in local_ips:
            return True
    return False<|return|>

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Try to extract named groups first
    name = None
    default = None
    if hasattr(matcher, "groupdict"):
        gd = matcher.groupdict()
        name = gd.get("name")
        default = gd.get("default")
    # Fallback to positional groups if named groups are not available
    if name is None:
        try:
            name = matcher.group(1)
        except IndexError:
            raise ValueError("Matcher does not contain a variable name")
        try:
            default = matcher.group(2)
        except IndexError:
            default = None

    # Retrieve the environment variable
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' not found and no default provided")
    return value<|return|>

