@classmethod
def from_ticks(cls, ticks, tz=None):
    if not isinstance(ticks, int):
        raise TypeError("ticks must be an integer")
    if ticks < 0 or ticks >= 86400000000000:
        raise ValueError("ticks out of bounds (0 <= ticks < 86400000000000)")
    total_seconds = ticks // 1_000_000_000
    remaining_ns = ticks % 1_000_000_000
    microsecond = remaining_ns // 1_000
    hour = total_seconds // 3600
    minute = (total_seconds % 3600) // 60
    second = total_seconds % 60
    return cls(hour=hour, minute=minute, second=second, microsecond=microsecond, tzinfo=tz)<|return|>

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, type):
        raise TypeError(f"candidate must be a class, got {type(candidate).__name__}")
    if not issubclass(candidate, iface):
        raise TypeError(f"{candidate.__name__} does not subclass {iface.__name__}")
    if not tentative:
        abstract = getattr(iface, "__abstractmethods__", set())
        for name in abstract:
            if not hasattr(candidate, name):
                raise TypeError(f"{candidate.__name__} missing abstract method {name}")
            attr = getattr(candidate, name)
            if not callable(attr):
                raise TypeError(f"{candidate.__name__}.{name} is not callable")
    return True<|return|>

