def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Check for a public message first
    if hasattr(request, "public_message") and request.public_message:
        return True

    # If no public message, check for a private message
    if hasattr(request, "private_message") and request.private_message:
        return True

    # Finally, check for a legacy payload
    if hasattr(request, "legacy_payload") and request.legacy_payload:
        # If the legacy payload is a mapping, look for known keys
        if isinstance(request.legacy_payload, dict):
            if "diaspora" in request.legacy_payload or "legacy" in request.legacy_payload:
                return True
        # If it's a string, look for a keyword
        if isinstance(request.legacy_payload, str) and "diaspora" in request.legacy_payload.lower():
            return True

    # If none of the checks matched, it's not a Diaspora request
    return False<|return|>

def identify_request(request: RequestType) -> bool:
    """
