def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        # Perform a HEAD request to get headers without downloading the body
        response = requests.head(url, allow_redirects=True, timeout=5)
        # Only consider successful responses
        if response.status_code == 200:
            # Return the Content-Type header if present
            return response.headers.get("Content-Type")
    except Exception:
        # Any error (network, timeout, invalid URL, etc.) results in None
        return None
    # If the status code is not 200 or header missing, return None
    return None<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    doc = document.strip()
    # Try JSON first
    try:
        data = json.loads(doc)
        # Ensure keys exist
        return {
            "subject": data.get("subject"),
            "aliases": data.get("aliases", []),
            "properties": data.get("properties", {}),
            "links": data.get("links", []),
        }
    except (json.JSONDecodeError, ValueError):
        pass

    # Fallback to XRD (XML)
    try:
        root = ET.fromstring(doc)
    except ET.ParseError as e:
        raise ValueError(f"Unable to parse webfinger document: {e}")

    ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
    subject_el = root.find("xrd:Subject", ns)
    subject = subject_el.text if subject_el is not None else None

    aliases = [el.text for el in root.findall("xrd:Alias", ns) if el.text]

    properties = {}
    for prop in root.findall("xrd:Property", ns):
        rel = prop.attrib.get("rel")
        if rel:
            properties[rel] = prop.text or ""

    links = []
    for link in root.findall("xrd:Link", ns):
        link_dict = dict(link.attrib)
        # Include nested elements if any (e.g., <Link> <Title>...</Title> </Link>)
        for child in link:
            tag = child.tag
            if tag.startswith("{"):
                # strip namespace
                tag = tag.split("}", 1)[1]
            link_dict[tag] = child.text
        links.append(link_dict)

    return {
        "subject": subject,
        "aliases": aliases,
        "properties": properties,
        "links": links,
    }<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict or None if retrieval/parsing fails
    """
    try:
        local, domain = handle.split('@', 1)
    except ValueError:
        return None
    resource = f'acct:{handle}'
    url = f'https://{domain}/.well-known/webfinger?resource={requests.utils.quote(resource)}'
    try:
        resp = requests.get(url, timeout=10)
        resp.raise_for_status()
        return resp.json()
    except Exception:
        return None<|return|>

