def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    spec_args = self.spec.get('arguments', [])
    for arg in spec_args:
        name = arg.get('name')
        if not name:
            continue
        # Priority: spec default, env var, config, then class defaults
        value = arg.get('default')
        env_var = arg.get('env_var')
        if value is None and env_var:
            value = self.env.get(env_var)
        if value is None and hasattr(self, 'config'):
            value = self.config.get(name)
        if value is None and hasattr(self, 'defaults'):
            value = self.defaults.get(name)
        defaults[name] = value
    return defaults<|return|>

