            silent.append(key)
    return silent<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    for opt in options_spec:
        # Resolve option name
        if isinstance(opt, dict):
            name = opt.get('name')
            cond = opt.get('required_when')
        else:
            name = getattr(opt, 'name', None)
            cond = getattr(opt, 'required_when', None)

        if not name or not cond:
            continue

        try:
            if callable(cond):
                match = cond(args)
            elif isinstance(cond, dict):
                # dict condition: all key/value pairs must match
                match = all(args.get(k) == v for k, v in cond.items())
            elif isinstance(cond, str):
                # string condition: evaluate in the context of args
                match = eval(cond, {}, args)
            else:
                match = False
        except Exception:
            # If evaluation fails, treat as not matched
            match = False

        if match:
            required.append(name)

    return required<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified."""
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")
    for key, value in args.items():
        # Determine the maximum allowed length for this argument
        max_len = getattr(self, f"{key}_max_length", None)
        if max_len is None:
            max_len = getattr(self, "max_length", None)
        if max_len is None:
            # No length constraint defined; skip this argument
            continue
        # Validate string values
        if isinstance(value, str):
            if len(value) > max_len:
                raise ValueError(f"Argument '{key}' exceeds maximum length of {max_len} characters.")
        # Validate iterable of strings (e.g., list or tuple)
        elif isinstance(value, (list, tuple)):
            for idx, item in enumerate(value):
                if isinstance(item, str) and len(item) > max_len:
                    raise ValueError(
                        f"Element {idx} of argument '{key}' exceeds maximum length of {max_len} characters."
                    )
        # For other types, no length check is performed
    return True<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Determine where the allowed choices are stored. Prefer _choices, fall back to choices.
    choices_map = getattr(self, "_choices", getattr(self, "choices", {}))
    for key, value in args.items():
        # Skip arguments that have no defined choices
        if key not in choices_map:
            continue
        allowed = choices_map[key]
        # If the value is an iterable (but not a string/bytes), validate each element
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{key}': {v}. "
                        f"Allowed choices: {allowed}"
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{key}': {value}. "
                    f"Allowed choices: {allowed}"
                )<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Can be a dict, list, tuple, or any iterable of values.
    :raises ValueError: If any numeric argument is outside the [min, max] range.
    :returns: True if all values are within bounds.
    """
    # Ensure min and max attributes exist
    if not hasattr(self, 'min') or not hasattr(self, 'max'):
        raise AttributeError("The validator must have 'min' and 'max' attributes defined.")
    min_val = self.min
    max_val = self.max

    # If args is a mapping, use its values; otherwise treat it as an iterable
    if isinstance(args, dict):
        iterable = args.values()
    else:
        iterable = args

    # If args is None or empty, nothing to validate
    if iterable is None:
        return True

    for val in iterable:
        # Skip non-numeric values
        if not isinstance(val, (int, float)):
            continue
        if val < min_val or val > max_val:
            raise ValueError(f"Argument value {val} out of bounds [{min_val}, {max_val}]")
    return True<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """
    Build a callable that parses a complex argument value according to the
    specification provided in *spec_option*.

    The returned callable can be used as the ``type`` argument in
    ``argparse`` or any other command‑line parsing library.

    Parameters
    ----------
    subcommand : str
        The name of the subcommand the option belongs to.
    type_name : str
        The name of the complex type being created (used only for error
        messages).
    option_name : str
        The name of the option being parsed.
    spec_option : dict
        A dictionary containing the specification for the option.  Supported
        keys include:

        * ``type`` (callable or str) – the type to cast each value to.
          If a string, one of ``'int'``, ``'float'``, ``'bool'`` or ``'str'``.
        * ``nargs`` (str) – ``'*'`` or ``'+'`` for a list of values,
          otherwise a single value.
        * ``default`` – the default value if the option is omitted.
        * ``required`` (bool) – whether the option is required.
        * ``choices`` (iterable) – a set of allowed values.

    Returns
    -------
    callable
        A function that accepts a single string argument (the raw value
        from the command line) and returns the parsed value.
    """
    # Resolve the type callable
    raw_type = spec_option.get("type", str)
    if isinstance(raw_type, str):
        if raw_type == "int":
            arg_type = int
        elif raw_type == "float":
            arg_type = float
        elif raw_type == "bool":
            def _bool(v):
                return v.lower() in ("true", "1", "yes", "y")
            arg_type = _bool
        else:
            arg_type = str
    else:
        arg_type = raw_type

    nargs = spec_option.get("nargs")
    default = spec_option.get("default")
    required = spec_option.get("required", False)
    choices = spec_option.get("choices")

    # Convert default to the correct type if provided
    if default is not None:
        try:
            if nargs in ("*", "+"):
                default = [arg_type(v) for v in default]
            else:
                default = arg_type(default)
        except Exception:
            # If conversion fails, keep the original default
            pass

    def _parse(value):
        # Handle missing value
        if value is None:
            if required:
                raise ValueError(
                    f"Option '{option_name}' is required for subcommand '{subcommand}'."
                )
            return default

        # Parse based on nargs
        if nargs in ("*", "+"):
            # Split on commas or whitespace
            parts = [p.strip() for p in value.replace(",", " ").split() if p.strip()]
            try:
                parsed = [arg_type(p) for p in parts]
            except Exception as exc:
                raise ValueError(
                    f"Failed to parse option '{option_name}' for subcommand '{subcommand}': {exc}"
                ) from exc
        else:
            try:
                parsed = arg_type(value)
            except Exception as exc:
                raise ValueError(
                    f"Failed to parse option '{option_name}' for subcommand '{subcommand}': {exc}"
                ) from exc

        # Validate choices if provided
        if choices is not None:
            if isinstance(parsed, list):
                for p in parsed:
                    if p not in choices:
                        raise ValueError(
                            f"Invalid value '{p}' for option '{option_name}' "
                            f"({type_name}) in subcommand '{subcommand}'. "
                            f"Allowed choices: {choices}"
                        )
            else:
                if parsed not in choices:
                    raise ValueError(
                        f"Invalid value '{parsed}' for option '{option_name}' "
                        f"({type_name}) in subcommand '{subcommand}'. "
                        f"Allowed choices: {choices}"
                    )

        return parsed

    return _parse<|return|>

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments into control and nested arguments.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file.
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args. It can be a list of tuples,
                 a list of dicts, or a single dict.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Normalise the input into an iterable of (key, value) pairs
    if isinstance(args, dict):
        items = args.items()
    else:
        items = args

    for item in items:
        # Handle a tuple or list of length 2
        if isinstance(item, (tuple, list)) and len(item) == 2:
            key, value = item
        # Handle a dict (e.g., a single dict in the list)
        elif isinstance(item, dict):
            for key, value in item.items():
                if isinstance(key, str) and key.startswith('_'):
                    control_args[key] = value
                else:
                    nested_args[key] = value
            continue
        else:
            # Skip malformed entries
            continue

        if isinstance(key, str) and key.startswith('_'):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args<|return|>

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: Updated dictionary
    """
    if not extra_vars:
        return vars_dict

    for var in extra_vars:
        if not isinstance(var, str) or '=' not in var:
            continue
        key, value = var.split('=', 1)
        key = key.strip()
        value = value.strip()
        # If the value contains commas, treat it as a list
        if ',' in value:
            value = [v.strip() for v in value.split(',')]
        vars_dict[key] = value

    return vars_dict<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict in place.
        By default all the values are strings.
        """
        # Define type mappings for known parsers
        type_map = {
            'main': {
                'count': int,
                'verbose': bool,
                'tags': list,
            },
            'virsh': {
                'timeout': int,
                'debug': bool,
            },
            'ospd': {
                'port': int,
                'config': str,
            },
        }

        # Get the mapping for the current parser, if any
        parser_map = type_map.get(parser_name, {})

        for key, val in list(values_dict.items()):
            # Skip if value is already not a string
            if not isinstance(val, str):
                continue

            # Determine target type
            target_type = parser_map.get(key)

            # If no explicit type, try generic heuristics
            if target_type is None:
                lowered = val.lower()
                if lowered in ('true', 'false'):
                    values_dict[key] = lowered == 'true'
                    continue
                try:
                    # Try integer
                    values_dict[key] = int(val)
                    continue
                except ValueError:
                    pass
                try:
                    # Try float
                    values_dict[key] = float(val)
                    continue
                except ValueError:
                    pass
                if ',' in val:
                    values_dict[key] = [item.strip() for item in val.split(',') if item.strip()]
                    continue
                # Default: keep as string
                continue

            # Cast to the target type
            try:
                if target_type is bool:
                    values_dict[key] = val.lower() in ('true', '1', 'yes', 'y')
                elif target_type is list:
                    values_dict[key] = [item.strip() for item in val.split(',') if item.strip()]
                else:
                    values_dict[key] = target_type(val)
            except Exception:
                # If casting fails, leave the original string
                pass

        # No return value; values_dict is modified in place.<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    def _flatten(d, parent_key=''):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    # Determine spec file
    json_path = os.path.join(plugin_dir, 'plugin.json')
    yaml_path = os.path.join(plugin_dir, 'plugin.yaml')
    spec = None

    if os.path.isfile(json_path):
        with open(json_path, 'r', encoding='utf-8') as f:
            spec = json.load(f)
    elif yaml and os.path.isfile(yaml_path):
        with open(yaml_path, 'r', encoding='utf-8') as f:
            spec = yaml.safe_load(f)
    else:
        raise FileNotFoundError("No plugin spec file found in the directory")

    if not isinstance(spec, dict):
        raise ValueError("Plugin spec must be a dictionary")

    return _flatten(spec)<|return|>

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        default_path = os.path.join(os.getcwd(), 'config.yaml')
        os.environ['CONFIG_PATH'] = default_path<|return|>
